import math

target = 2007

def solve_quadratic(n):
    discriminant = 24084 - 3 * (n**2)
    if discriminant < 0:
        return []

    sqrt_d = math.isqrt(discriminant)
    if sqrt_d * sqrt_d != discriminant:
        return []

    # Check the two solutions for r
    r1_num = 3 * n + sqrt_d
    r2_num = 3 * n - sqrt_d

    solutions = []

    if r1_num % 6 == 0:
        r1 = r1_num // 6
        if 1 <= r1 <= n - 1:
            solutions.append((n, r1))

    if r2_num % 6 == 0:
        r2 = r2_num // 6
        if 1 <= r2 <= n - 1:
            solutions.append((n, r2))

    return solutions

results = {}
# Search n up to where the discriminant becomes negative (n <= 89)
for n in range(1, 90):
    solutions = solve_quadratic(n)
    if solutions:
        results[n] = solutions

print("Found solutions (n, r) under the quadratic approximation:")
for n, r in results.items():
